VALUES
('obs_claim_pd10_c01',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'nonprofit_role','Diamandis founded XPRIZE and serves as executive chairman, while Anousheh Ansari has served as CEO since 2018.','formal_role','observed','unreviewed',NULL,'Founder and executive chairman of XPRIZE within separate executive governance.','XPRIZE is not established as a personally owned asset and executive chairman is not sole operating authority.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c02',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'cofounding_history','Singularity was co-founded by Diamandis and Ray Kurzweil in 2008.','venture_history','observed','unreviewed',NULL,'Co-founder of Singularity.','No sole-founder, sole-authorship or current-control inference.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c03',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'role_transition','Singularity announced in 2018 that Diamandis would become executive founder and remain on its board after a financing.','role_transition','observed','unreviewed',NULL,'His Singularity role changed within a separately financed institution.','A historic board role does not prove unchanged current control.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c04',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'cofounding_history','Human Longevity was formed with co-founders J. Craig Venter and Robert Hariri.','venture_history','corroborated','unreviewed',NULL,'Co-founder of Human Longevity with Venter and Hariri.','No sole-creation, current-control or personal-value claim.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c05',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'governance_role','Celularity filings document Diamandis as a predecessor co-founder and director within a multi-person board.','formal_governance','primary_filing','unreviewed',NULL,'Co-founder and director of Celularity.','Director status does not establish majority ownership, voting control or personal receipt of company value.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c06',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'governance_role','Vaxxinity filings document a director role alongside CEO Mei Mei Hu and other directors.','formal_governance','primary_filing','unreviewed',NULL,'Held a formal Vaxxinity governance role.','No sole-control, product-authorship or personal-performance inference.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c07',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'portfolio_boundary','Fountain Life and BOLD identify Diamandis as one of multiple founders or partners within separately led institutions.','distributed_portfolio','observed','unreviewed',NULL,'Co-founder or partner within Fountain Life and BOLD.','Fund size, company value and portfolio value are not personal wealth or proof of portfolio-company ownership.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c08',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'adverse_event','Independent reporting tied the January 2021 Abundance360 gathering to at least 24 reported COVID-19 cases, and Diamandis acknowledged that the attempted safety approach failed.','adverse_event','attributed','unreviewed',NULL,'Reporting documents an outbreak and Diamandis’s public correction.','Do not convert the event into a psychological diagnosis or timeless trait.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c09',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'claim_restriction','Portfolio counts, fund size, competition value, company valuation and induced research-and-development estimates are source-defined institutional metrics.','claim_restriction','observed','unreviewed',NULL,'Use aggregate metrics only with source, date and definition.','Do not convert them into personal ownership, income, wealth or sole impact.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_pd10_c10',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='peter-diamandis' LIMIT 1),'claim_restriction','No reviewed record establishes a complete portfolio cap table, cross-entity contracts, personal economics, sole causal output or psychological measurements.','claim_restriction','observed','unreviewed',NULL,'Public evidence establishes bounded roles, not complete control, economics, causality or psychology.','Absence of public evidence is not proof that no private rights exist.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
